const getCurrentPricing = `-- name: GetCurrentPricing :many
SELECT id, distance_id, name, price, start_date, end_date, is_early_bird, created_at FROM pricing_stages
WHERE distance_id = $1
  AND start_date <= CURRENT_DATE
  AND end_date >= CURRENT_DATE
ORDER BY price ASC
`

func (q *Queries) GetCurrentPricing(ctx context.Context, distanceID uuid.UUID) ([]PricingStage, error) {
	rows, err := q.db.Query(ctx, getCurrentPricing, distanceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PricingStage{}
	for rows.Next() {
		var i PricingStage
		if err := rows.Scan(
			&i.ID,
			&i.DistanceID,
			&i.Name,
			&i.Price,
			&i.StartDate,
			&i.EndDate,
			&i.IsEarlyBird,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

