const upsertEventFieldConfig = `-- name: UpsertEventFieldConfig :one
INSERT INTO event_field_config (
    event_id, section_name, is_enabled, is_required
) VALUES (
    $1, $2, $3, $4
)
ON CONFLICT (event_id, section_name)
DO UPDATE SET
    is_enabled = $3,
    is_required = $4,
    updated_at = NOW()
RETURNING id, event_id, section_name, is_enabled, is_required, created_at, updated_at
`

type UpsertEventFieldConfigParams struct {
	EventID     uuid.UUID `json:"event_id"`
	SectionName string    `json:"section_name"`
	IsEnabled   bool      `json:"is_enabled"`
	IsRequired  bool      `json:"is_required"`
}

func (q *Queries) UpsertEventFieldConfig(ctx context.Context, arg UpsertEventFieldConfigParams) (EventFieldConfig, error) {
	row := q.db.QueryRow(ctx, upsertEventFieldConfig,
		arg.EventID,
		arg.SectionName,
		arg.IsEnabled,
		arg.IsRequired,
	)
	var i EventFieldConfig
	err := row.Scan(
		&i.ID,
		&i.EventID,
		&i.SectionName,
		&i.IsEnabled,
		&i.IsRequired,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

